package io.atlas.modules.market.menu;
import net.minecraft.world.inventory.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.item.*;import net.minecraft.world.SimpleContainer;import net.minecraft.server.level.ServerPlayer;import io.atlas.modules.market.MarketModule;
/** Selection is a preview. The actual stack returns to inventory before the price menu opens. */
public final class MarketItemSelectMenu extends ChestMenu {
 private boolean used;
 public MarketItemSelectMenu(int id,Inventory inventory){this(id,inventory,new SimpleContainer(27));}
 private MarketItemSelectMenu(int id,Inventory inventory,SimpleContainer contents){super(MenuType.GENERIC_9x3,id,inventory,contents,3);for(int i=0;i<27;i++){if(i!=13)contents.setItem(i,MarketVisual.icon(Items.GRAY_STAINED_GLASS_PANE," "));var old=slots.get(i);var locked=new Slot(contents,i,old.x,old.y){@Override public boolean mayPlace(ItemStack stack){return false;}@Override public boolean mayPickup(Player player){return false;}};locked.index=i;slots.set(i,locked);}contents.setItem(4,MarketVisual.icon(Items.CHEST,"§6Escolher item","§7Pegue uma pilha no inventário","§7e arraste para o espaço central."));contents.setItem(22,MarketVisual.icon(Items.ARROW,"§eVoltar"));}
 @Override public void clicked(int slot,int button,ClickType type,Player player){if(!(player instanceof ServerPlayer p)||used)return;if(slot==22&&type==ClickType.PICKUP){used=true;MarketModule.service().announce(p);return;}if(slot==13&&(type==ClickType.PICKUP||type==ClickType.QUICK_CRAFT&&(button&3)==1)&&!getCarried().isEmpty()){if(!MarketModule.service().eligible(p))return;var selected=getCarried().copy();var carried=getCarried();p.getInventory().add(carried);if(!carried.isEmpty()){p.sendSystemMessage(net.minecraft.network.chat.Component.literal("§cLibere espaço no inventário para selecionar essa pilha."));broadcastChanges();return;}setCarried(ItemStack.EMPTY);p.getInventory().setChanged();used=true;MarketModule.service().priceSelectedItem(p,selected);return;}if(slot>=27||slot<0)super.clicked(slot,button,type,player);}
 @Override public ItemStack quickMoveStack(Player player,int slot){return ItemStack.EMPTY;}
}
